size(84, 3, 17, 1.25);
name("knightly arming sword");

// The sword lies on its flat along x: pommel at x 0, point at x 83.
// y 1 is the plane of the blade; k counts cells out from the centre line (z = C).
var C = 8;
var GOLD = "3:3", SHINE = "3:2", DEEP = "3:5", BRASS = "3:8", RUBY = "0:5";
var HIDE = "2:6", HIDE2 = "1:6", WORN = "2:9";

function S(col, x, y, k) { put("steel", col, x, y, C + k); }
function W(col, x, y, k) { put("wood", col, x, y, C + k); }

// a tone that holds for a few cells before it changes, so the steel streaks instead of speckling
var runs = {};
function streak(key, pick) {
  var r = runs[key];
  if (!r) r = runs[key] = { left: 0, tone: "" };
  if (r.left <= 0) { r.tone = pick(); r.left = 2 + Math.floor(rng() * 5); }
  r.left--;
  return r.tone;
}
function pickEdge() { var r = rng(); return r < 0.2 ? "grey:1" : r < 0.9 ? "grey:2" : "grey:3"; }
function pickFlat() { var r = rng(); return r < 0.55 ? "grey:5" : r < 0.85 ? "grey:4" : "grey:6"; }
function pickRidge() { return rng() < 0.3 ? "grey:2" : "grey:3"; }
function pickMid() { return rng() < 0.35 ? "grey:3" : "grey:4"; }

// ---------- blade: 67 cells, parallel edges, ogival point ----------
var BLADE0 = 17, TIP = 83, RIDGE_END = 62;
function half(x) { return x <= 71 ? 2 : x <= 80 ? 1 : 0; }

for (var x = BLADE0; x <= TIP; x++) {
  var h = half(x);
  for (var k = -h; k <= h; k++) {
    var a = Math.abs(k), side = k < 0 ? "L" : "R", col;
    if (h === 0) col = x === TIP ? "grey:1" : "grey:2";
    else if (a === h) col = streak("edge" + side, pickEdge);
    else if (a === 0) col = h === 2 ? streak("mid", pickMid) : streak("point", pickFlat);
    else if (x === BLADE0) col = "grey:7";
    else if (x <= BLADE0 + 2) col = "grey:6";
    else col = streak("flat" + side, pickFlat);
    S(col, x, 1, k);
  }
}

// two old nicks in the edges
S("grey:4", 41, 1, 2);
S("grey:4", 56, 1, -2);

// raised medial ridge on both faces for the strong two thirds; the lower one is what the blade rests on
for (var x = BLADE0 + 1; x <= RIDGE_END; x++) {
  var fade = x === BLADE0 + 1 || x === RIDGE_END;
  S(fade ? "grey:4" : streak("ridgeUp", pickRidge), x, 2, 0);
  S(fade ? "grey:4" : streak("ridgeDown", pickRidge), x, 0, 0);
}

// small cross inlaid in gold near the hilt, on both faces
for (var x = 22; x <= 24; x++) { S(GOLD, x, 2, 0); S(GOLD, x, 0, 0); }
S(GOLD, 23, 1, -1);
S(GOLD, 23, 1, 1);

// ---------- cross-guard: stout at the middle, thinning, tips swept toward the blade ----------
for (var k = -8; k <= 8; k++) {
  var a = Math.abs(k);
  if (a <= 3) {
    var c = a === 2 ? DEEP : GOLD;
    S(c, 15, 1, k);
    S(c, 16, 1, k);
  } else if (a <= 6) {
    S(a === 6 ? DEEP : a === 5 ? BRASS : GOLD, 16, 1, k);
  } else {
    S(a === 8 ? SHINE : GOLD, 16, 1, k);
    S(SHINE, 17, 1, k);
  }
}
// the block at its middle, with a cusp reaching onto the blade
for (var y = 0; y <= 2; y += 2) {
  for (var x = 15; x <= 16; x++) {
    for (var k = -1; k <= 1; k++) S(k === 0 ? SHINE : GOLD, x, y, k);
  }
  S(GOLD, 17, y, 0);
}

// ---------- grip: steel tang inside, leather over wood, three risers ----------
for (var x = 6; x <= 14; x++) {
  S("grey:7", x, 1, 0);
  if (x === 6 || x === 10 || x === 14) {
    for (var y = 0; y <= 2; y++) {
      for (var k = -1; k <= 1; k++) {
        if (y !== 1 || k !== 0) W(WORN, x, y, k);
      }
    }
  } else {
    var even = x % 2 === 0;
    var top = even ? HIDE : HIDE2, flank = even ? HIDE2 : HIDE;
    if (rng() < 0.15) top = WORN;
    W(top, x, 0, 0);
    W(top, x, 2, 0);
    W(flank, x, 1, -1);
    W(flank, x, 1, 1);
  }
}

// ---------- wheel pommel with a raised face and a red stone, peened button at the end ----------
var PX = 3;
for (var dx = -2; dx <= 2; dx++) {
  for (var dk = -2; dk <= 2; dk++) {
    var d2 = dx * dx + dk * dk;
    if (d2 > 5) continue;
    S(d2 >= 4 ? BRASS : GOLD, PX + dx, 1, dk);
    if (d2 <= 2) {
      var face = d2 === 0 ? RUBY : d2 === 1 ? SHINE : GOLD;
      S(face, PX + dx, 0, dk);
      S(face, PX + dx, 2, dk);
    }
  }
}
S(DEEP, 0, 1, 0);
